def transform(grid):
    g = np.array(grid)
    out = g.copy()
    fg = 8
    # shape -> colour legend read off the train pairs
    shapes = {
        1: [(0, 0), (0, 1), (1, 0), (1, 1)],   # 2x2 square
        2: [(0, 1), (1, 0), (1, 1)],           # L missing top-left
        3: [(0, 0), (0, 1), (1, 1)],           # L missing bottom-left
        4: [(0, 0), (1, 0), (1, 1)],           # L missing top-right
    }
    # normalise each shape relative to its first cell in reading order
    norm = {}
    for c, cells in shapes.items():
        f = min(cells)
        norm[c] = [(y - f[0], x - f[1]) for y, x in cells]

    H, W = g.shape
    target = set(zip(*np.where(g == fg)))
    order = sorted(target)

    def solve(limit_L):
        covered = set()
        placed = []
        used = {2: 0, 3: 0, 4: 0}

        def rec():
            nxt = None
            for p in order:
                if p not in covered:
                    nxt = p
                    break
            if nxt is None:
                if limit_L == 'exact':
                    return all(v == 1 for v in used.values())
                return True
            for c in (1, 2, 3, 4):
                if c != 1 and limit_L in ('exact', 'atmost') and used[c] >= 1:
                    continue
                cells = [(nxt[0] + dy, nxt[1] + dx) for dy, dx in norm[c]]
                if all(q in target and q not in covered for q in cells):
                    covered.update(cells)
                    placed.append((c, cells))
                    if c != 1:
                        used[c] += 1
                    if rec():
                        return True
                    if c != 1:
                        used[c] -= 1
                    placed.pop()
                    for q in cells:
                        covered.discard(q)
            return False

        return placed if rec() else None

    placed = solve('exact') or solve('atmost') or solve('any') or []
    for c, cells in placed:
        for y, x in cells:
            out[y, x] = c
        emit(out.copy(), f"Colour a {'2x2 square' if c == 1 else 'L-tromino'} piece of the 8-region with colour {c}.")
    emit(out.copy(), "All pieces of the region are coloured by shape.")
    return out
